{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C13"],
      "claim": "Adiphenine, a diphenylacetate ester with a basic aminoethyl group, has a brain uptake index of 110 after carotid injection and high brain concentrations after i.v. dosing, showing that the diphenylacetyl/basic-amine scaffold is CNS-permeable.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Methylphenidate, a 2-phenyl-2-piperidinyl acetate, achieves brain-to-plasma ratios of 10.6-11.2 in rats, supporting CNS access for the related 2,2-diphenylacetamide tertiary amine in the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "RS2360, a lipophilic tertiary N-methyl amide with a chiral center, shows rapid high brain uptake (7.08 %ID/g at 1 min), supporting that the amide/chiral lipophilic motif in the query is brain-penetrant.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "4-DAMP has negligible brain uptake because it is a permanently charged quaternary ammonium; the query is a tertiary amine lacking this charge, so this impermeability evidence does not transfer.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C11"],
      "claim": "DiPOA has a very low brain-to-plasma ratio (0.019), but it contains a carboxylic acid and multiple polar/ionizable groups; the query is a neutral amide with no acid, so this poor-penetration result is not directly applicable.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Pass: the query is a lipophilic tertiary-amine amide built on the diphenylacetyl/basic-amine scaffold of CNS-permeable adiphenine and methylphenidate; the main fail signals come from quaternary ammonium or carboxylic-acid analogues that do not apply to this structure.",
  "evidence_gaps": [
    "No direct brain/plasma, CSF, or uptake measurement for the query itself.",
    "Efflux-transporter liability of the query is not directly measured.",
    "The effect of the 3-hydroxypyrrolidine group on net brain penetration is inferred from analogues rather than measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

